create extension if not exists pgcrypto;
create type public.org_role as enum ('OWNER','ADMIN','SCORER','STATISTICIAN','COACH','VIEWER');
create type public.game_status as enum ('DRAFT','SCHEDULED','LIVE','FINAL','CANCELLED');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', created_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, sport text not null default 'BASKETBALL', created_at timestamptz not null default now());
create table public.organization_members(organization_id uuid references public.organizations on delete cascade, user_id uuid references auth.users on delete cascade, role public.org_role not null, active boolean not null default true, primary key(organization_id,user_id));
create table public.seasons(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, starts_on date, ends_on date, active boolean default true);
create table public.competitions(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, season_id uuid references public.seasons on delete cascade, name text not null, format text not null default 'LEAGUE');
create table public.venues(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, address text);
create table public.teams(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, code text, logo_path text, active boolean default true);
create table public.players(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, first_name text not null, last_name text not null, birth_date date, jersey_name text, photo_path text, active boolean default true, created_at timestamptz default now());
create table public.rosters(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, season_id uuid not null references public.seasons on delete cascade, team_id uuid not null references public.teams on delete cascade, player_id uuid not null references public.players on delete cascade, jersey_number int, position text, status text default 'ACTIVE', unique(season_id,team_id,player_id));
create table public.games(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, competition_id uuid references public.competitions, season_id uuid references public.seasons, venue_id uuid references public.venues, home_team_id uuid not null references public.teams, away_team_id uuid not null references public.teams, scheduled_at timestamptz, status public.game_status not null default 'DRAFT', current_period int not null default 1, clock_ms int not null default 600000, home_score int not null default 0, away_score int not null default 0, finalized_at timestamptz, check(home_team_id<>away_team_id));
create table public.game_events(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, game_id uuid not null references public.games on delete cascade, team_id uuid not null references public.teams, player_id uuid references public.players, event_type text not null, period int not null, clock_ms int not null, points int not null default 0, actor_id uuid not null references auth.users, reversed_event_id uuid references public.game_events, reason text, created_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key, organization_id uuid references public.organizations on delete cascade, actor_id uuid references auth.users, action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index on public.organization_members(user_id); create index on public.games(organization_id,scheduled_at); create index on public.game_events(game_id,created_at);
create or replace function public.is_org_member(p_org uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_members where organization_id=p_org and user_id=auth.uid() and active)$$;
create or replace function public.has_org_role(p_org uuid,p_roles public.org_role[]) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_members where organization_id=p_org and user_id=auth.uid() and active and role=any(p_roles))$$;
alter table public.profiles enable row level security; alter table public.organizations enable row level security; alter table public.organization_members enable row level security; alter table public.seasons enable row level security; alter table public.competitions enable row level security; alter table public.venues enable row level security; alter table public.teams enable row level security; alter table public.players enable row level security; alter table public.rosters enable row level security; alter table public.games enable row level security; alter table public.game_events enable row level security; alter table public.audit_log enable row level security;
create policy profile_self on public.profiles for select using(id=auth.uid());
create policy org_member_read on public.organizations for select using(public.is_org_member(id));
create policy member_read on public.organization_members for select using(public.is_org_member(organization_id));
create policy season_read on public.seasons for select using(public.is_org_member(organization_id)); create policy comp_read on public.competitions for select using(public.is_org_member(organization_id)); create policy venue_read on public.venues for select using(public.is_org_member(organization_id)); create policy team_read on public.teams for select using(public.is_org_member(organization_id)); create policy player_read on public.players for select using(public.is_org_member(organization_id)); create policy roster_read on public.rosters for select using(public.is_org_member(organization_id)); create policy game_read on public.games for select using(public.is_org_member(organization_id)); create policy event_read on public.game_events for select using(public.is_org_member(organization_id)); create policy audit_admin_read on public.audit_log for select using(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[]));
create policy season_write on public.seasons for all using(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])) with check(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])); create policy comp_write on public.competitions for all using(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])) with check(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])); create policy venue_write on public.venues for all using(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])) with check(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])); create policy team_write on public.teams for all using(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])) with check(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])); create policy player_write on public.players for all using(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])) with check(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])); create policy roster_write on public.rosters for all using(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])) with check(public.has_org_role(organization_id,array['OWNER','ADMIN']::public.org_role[])); create policy game_write on public.games for all using(public.has_org_role(organization_id,array['OWNER','ADMIN','SCORER']::public.org_role[])) with check(public.has_org_role(organization_id,array['OWNER','ADMIN','SCORER']::public.org_role[]));
create or replace function public.record_game_event(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare v_game games; v_points int:=case p_payload->>'event_type' when 'FT_MADE' then 1 when '2PT_MADE' then 2 when '3PT_MADE' then 3 else 0 end; v_event game_events; begin select * into v_game from games where id=(p_payload->>'game_id')::uuid for update; if not found then raise exception 'GAME_NOT_FOUND'; end if; if not exists(select 1 from organization_members where organization_id=v_game.organization_id and user_id=p_actor and active and role in ('OWNER','ADMIN','SCORER','STATISTICIAN')) then raise exception 'FORBIDDEN'; end if; if v_game.status<>'LIVE' then raise exception 'GAME_NOT_LIVE'; end if; insert into game_events(organization_id,game_id,team_id,player_id,event_type,period,clock_ms,points,actor_id) values(v_game.organization_id,v_game.id,(p_payload->>'team_id')::uuid,nullif(p_payload->>'player_id','')::uuid,p_payload->>'event_type',(p_payload->>'period')::int,(p_payload->>'clock_ms')::int,v_points,p_actor) returning * into v_event; if v_points>0 then if v_event.team_id=v_game.home_team_id then update games set home_score=home_score+v_points where id=v_game.id; elsif v_event.team_id=v_game.away_team_id then update games set away_score=away_score+v_points where id=v_game.id; else raise exception 'TEAM_NOT_IN_GAME'; end if; end if; insert into audit_log(organization_id,actor_id,action,entity_type,entity_id,metadata) values(v_game.organization_id,p_actor,'CREATE','GAME_EVENT',v_event.id::text,to_jsonb(v_event)); return to_jsonb(v_event); end$$;
create or replace function public.reverse_game_event(p_actor uuid,p_event_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=public as $$declare v game_events; r game_events; g games; begin select * into v from game_events where id=p_event_id for update; if not found or v.reversed_event_id is not null then raise exception 'EVENT_NOT_REVERSIBLE'; end if; if not exists(select 1 from organization_members where organization_id=v.organization_id and user_id=p_actor and active and role in ('OWNER','ADMIN','SCORER')) then raise exception 'FORBIDDEN'; end if; select * into g from games where id=v.game_id for update; insert into game_events(organization_id,game_id,team_id,player_id,event_type,period,clock_ms,points,actor_id,reversed_event_id,reason) values(v.organization_id,v.game_id,v.team_id,v.player_id,'REVERSAL',v.period,v.clock_ms,-v.points,p_actor,v.id,p_reason) returning * into r; if v.points>0 then if v.team_id=g.home_team_id then update games set home_score=greatest(0,home_score-v.points) where id=g.id; else update games set away_score=greatest(0,away_score-v.points) where id=g.id; end if; end if; insert into audit_log(organization_id,actor_id,action,entity_type,entity_id,metadata) values(v.organization_id,p_actor,'REVERSE','GAME_EVENT',v.id::text,jsonb_build_object('reason',p_reason,'reversal_id',r.id)); return to_jsonb(r); end$$;
create or replace view public.player_game_stats as select game_id,player_id,team_id,sum(points) points,count(*) filter(where event_type like 'REBOUND_%') rebounds,count(*) filter(where event_type='ASSIST') assists,count(*) filter(where event_type='STEAL') steals,count(*) filter(where event_type='BLOCK') blocks,count(*) filter(where event_type='TURNOVER') turnovers,count(*) filter(where event_type='FOUL') fouls from game_events where reversed_event_id is null group by game_id,player_id,team_id;
